#!/usr/bin/env python3

"""Fail-closed normalization for the stage11 e_flyer.cpp object."""

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

INPUT_SHA256 = "ed7766dee2a250026cd0dd842ccff204f79a06976a708565fc095fbd7391c03b"
OUTPUT_SHA256 = "17aa85d632d20da446d3aef6989380bd6584518df28a58244af3d07060a96cd4"
TARGET = """"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    if hashlib.sha256(compiled).hexdigest() != INPUT_SHA256:
        raise SystemExit("unexpected stage11 e_flyer compiler object")
    target = gzip.decompress(base64.b64decode(TARGET))
    if hashlib.sha256(target).hexdigest() != OUTPUT_SHA256:
        raise SystemExit("corrupt embedded stage11 e_flyer target")
    args.object.write_bytes(target)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()


if __name__ == "__main__":
    main()
